/// <summary>
///    AVA <c>avaCalcKCS_PickingReleaseIndicator</c> method.
/// </summary>
/// <returns>
///    <c>KCS_PickingReleaseIndicator</c> as return value
/// </returns>
public KCS_PickingReleaseIndicator avaCalcKCS_PickingReleaseIndicator()
{
    KCS_PickingReleaseIndicator retVal;

    KCS_PickingReleaseIndicator locKCS_PickingReleaseIndicator;

    InventTransferTable         locInventTransferTable;
    InventTransferLine          locInventTransferLine;

    int                         noOfSalesLinesReleaseForShipment;
    int                         noOfSalesLinesNoReleaseForShipmentWithRemainQty;

    locInventTransferTable          = this;

    retVal                          = locInventTransferTable.KCS_PickingReleaseIndicator;
    locKCS_PickingReleaseIndicator  = locInventTransferTable.KCS_PickingReleaseIndicator;

    select firstonly locInventTransferLine
    where   locInventTransferLine.TransferId                        == this.TransferId
        &&  locInventTransferLine.KCS_SOCPickingReleaseIndicator    == NoYes::Yes;
    if(!locInventTransferLine.RecId)
    {
        retVal = KCS_PickingReleaseIndicator::NotReleased;
    }
    else
    {
        while select locInventTransferLine
        where   locInventTransferLine.TransferId == this.TransferId
        {
            if(locInventTransferLine.KCS_SOCPickingReleaseIndicator == NoYes::Yes)
            {
                noOfSalesLinesReleaseForShipment++;
            }
            else
            {
                if(locInventTransferLine.QtyRemainShip > 0)
                {
                    noOfSalesLinesNoReleaseForShipmentWithRemainQty++;
                }
            }
        }

        if(noOfSalesLinesReleaseForShipment > 0)
        {
            if(noOfSalesLinesNoReleaseForShipmentWithRemainQty == 0)
            {
                retVal = KCS_PickingReleaseIndicator::CompleteReleased;
            }
            else
            {
                retVal = KCS_PickingReleaseIndicator::PartReleased;
            }
        }
    }

    return retVal;
}

/// <summary>
/// Checks if an InventTransterTable record exists with the specified ProdId reference
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <returns>boolean</returns>
public static boolean avaExistsProdIdOrder(ProdId _prodId)
{
    InventTransferTable transferTable;

    select firstonly RecId from transferTable
        where transferTable.AVAPOReference == _prodId;

    return _prodId
        && transferTable.RecId != 0;
}

/// <summary>
/// Returns an InventTransterTable record with the specified ProdId reference
/// </summary>
/// <param name = "_prodId">ProdId</param>
/// <param name = "_selectForUpdate">boolean</param>
/// <returns>boolean</returns>
public static InventTransferTable avaFindProdId(ProdId _prodId, boolean _selectForUpdate = false)
{
    InventTransferTable transferTable;

    if(_selectForUpdate)
    {
        transferTable.selectForUpdate(_selectForUpdate);
    }

    select firstonly transferTable
        where transferTable.AVAPOReference == _prodId;

    return transferTable;
}

/// <summary>
///    AVA <c>avaGetGrossWeightRemaining</c> method.
/// </summary>
/// <returns>
///     <c>ItemGrossWeight</c> as type
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display ItemGrossWeight avaGetGrossWeightRemaining()
{
    ItemGrossWeight retVal;

    InventTransferLine locInventTransferLine;

    while select locInventTransferLine
    where   locInventTransferLine.TransferId == this.TransferId
    {
        retVal += locInventTransferLine.QtyRemainShip * locInventTransferLine.avaGetItemGrossWeightFromInventUnit(); // ToDo: check remainInventPhysical
    }

    return retVal;
}

