/// <summary>
///    Called by the kernel when a field on the table has its value modified.
/// </summary>
/// <param name="_fieldId">
///    The field ID of the changed field.
/// </param>
/// <remarks>
///    This method calls methods that should be called when a field value changes.
/// </remarks>
public void modifiedField(FieldId _fieldId)
{

    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(InventTransferTable, InventLocationIdFrom):
            if(this.InventLocationIdFrom)
            {
                this.KCS_InventSiteIdFrom = InventLocation::find(this.InventLocationIdFrom).InventSiteId;
            }
            else
            {
                this.KCS_InventSiteIdFrom = '';
            }
            break;
    }
}

/// <summary>
///    AVA <c>avaHasItemSetPositionExpandable</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean avaHasItemSetPositionExpandable()
{
    boolean retVal;

    InventTransferLine  locInventTransferLine;

    select firstonly locInventTransferLine
    where   locInventTransferLine.TransferId == this.TransferId
        &&  locInventTransferLine.AVAItemSet
        &&  !locInventTransferLine.AVAItemSetExpanded;

    if(locInventTransferLine.RecId)
    {
        retVal = true;
    }

    return retVal;
}

/// <summary>
///     AVA <c>avaItemSetExpandPossiblePositions</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
/// <param name="_inventTransferId">
///     <c>InventTransferId</c> as type
/// </param>
/// <returns>
///     <c>boolean</c> as return value
/// </returns>
public static boolean avaItemSetExpandPossiblePositions(Args                _args,
                                                        InventTransferId    _inventTransferId   )
{
    boolean                                 retVal;

    Args                                    locArgs;
    InventTransferTable                     locInventTransferTable;
    InventTransferLine                      locInventTransferLine;
    AVAItemSetInventTransferLineExplodeBOM  locClassInstance;

    retVal  = true;
    locArgs = new Args();

    locInventTransferTable  = InventTransferTable::find(_inventTransferId);
    if(locInventTransferTable.RecId)
    {
        while select locInventTransferLine
        where   locInventTransferLine.TransferId == _inventTransferId
            &&  locInventTransferLine.AVAItemSet
            &&  !locInventTransferLine.AVAItemSetExpanded
        {
            locArgs.caller(_args.caller());
            locArgs.record(InventTransferLine::findTransIdShip(locInventTransferLine.InventTransId)); // get actual InventTransferLine again because of reorganization of LinNum

            locClassInstance = AVAItemSetInventTransferLineExplodeBOM::newFromArgs(locArgs);
            locClassInstance.init();
            locClassInstance.run();
        }
    }

    return retVal;
}

public void setInventTransferStatus()
{
    next setInventTransferStatus();

    InventTransferLine  inventTransferLine;

    select maxof(RemainStatus) from inventTransferLine
        where inventTransferLine.TransferId == this.TransferId
           && (inventTransferLine.AVAItemSet == NoYes::No
           || (inventTransferLine.AVAItemSet == NoYes::Yes && inventTransferLine.AVAItemSetExpanded == NoYes::No));

    if (!inventTransferLine)
    {
        this.TransferStatus = InventTransferStatus::Created;
        return;
    }

    switch (inventTransferLine.RemainStatus)
    {
        case InventTransferRemainStatus::None:
            this.TransferStatus = InventTransferStatus::Received;
            break;

        case InventTransferRemainStatus::Receiving:
            this.TransferStatus = InventTransferStatus::Shipped;
            break;

        case InventTransferRemainStatus::Shipping:
            this.TransferStatus = InventTransferStatus::Created;
            break;

        default:
            this.TransferStatus = InventTransferStatus::Created;
            break;
    }
}

/// <summary>
/// sets init values based on ProdTable and ProdBOM
/// </summary>
/// <param name = "_prodTable">ProdTable</param>
/// <param name = "_prodBOM">ProdBOM</param>
public void avaInitPOTransfer(
    ProdTable _prodTable, 
    ProdBOM _prodBOM)
{
    this.InventLocationIdTo          = _prodBom.inventDim().InventLocationId;
    this.modifiedField(fieldNum(InventTransferTable, InventLocationIdTo));

    this.InventLocationIdFrom        = _prodTable.inventDim().InventLocationId;
    this.modifiedField(fieldNum(InventTransferTable, InventLocationIdFrom));

    this.AVAPOReference              = _prodTable.ProdId;
    this.AVAProdItemId               = _prodTable.ItemId;
    this.TransferStatus              = InventTransferStatus::Created;
    this.AutoReservation             = NoYes::No;
    this.KCS_PickingReleaseIndicator = KCS_PickingReleaseIndicator::NotReleased;
    this.KCS_TransferType            = KCS_TransferType::ExternalProduction;
    this.KCS_InventSiteIdFrom        = InventLocation::find(this.InventLocationIdFrom).InventSiteId;
    this.InventLocationIdTransit     = InventLocation::find(this.InventLocationIdFrom).InventLocationIdTransit;
}
